window.BOOK={"key":"zuhayr","app":"mutoon-zuhayr","lsk":"mutoon_zuhayr_v1","prefix":"zu_","title":"معلقة زهير بن أبي سلمى","sub":"معلقة · زهير بن أبي سلمى (ت نحو ٦٠٩م) · ٦٢ بيتًا","poems":[{"id":"zuhayr","title":"معلقة زهير بن أبي سلمى","nazim":"زهير بن أبي سُلمى المزني","death":"ت نحو ٦٠٩م","meter":"الطويل","source":"المكتبة الشاملة: شرح المعلقات السبع للزوزني (دار إحياء التراث العربي، ١٤٢٣هـ)","srcUrl":"https://shamela.ws/book/11253/143","note":"النص برواية الزوزني وترتيبه (٦٢ بيتًا، ومنها أبيات الحكمة الأخيرة التي ليست عند التبريزي وابن الأنباري)، قوبل كلمةً كلمةً بسكربت بشرحيهما وبنسختي ويكي مصدر، وأُكمل شكله مما ورد فيها، وفُحص وزن كل بيت على الطويل. التفاصيل في تقرير المصادر.","verses":[["أَمِنْ أُمِّ أَوْفَى دِمْنَةٌ لَمْ تَكَلَّمِ","بِحَوْمَانَةِ الدَّرَّاجِ فَالْمُتَثَلَّمِ"],["وَدَارٌ لَهَا بِالرَّقْمَتَيْنِ كَأَنَّهَا","مرَاجيعُ وَشْمٍ فِي نَوَاشِرِ مِعْصَمِ"],["بِهَا العِينُ وَالأَرْآمُ يَمْشِينَ خِلْفَةً","وَأَطْلَاؤُهَا يَنْهَضْنَ مِنْ كُلِّ مَجْثَمِ"],["وَقَفْتُ بِهَا مِنْ بَعْدِ عِشْرِينَ حِجَّةً","فَلأْيًا عَرَفْتُ الدَّارَ بَعْدَ تَوَهُّمِ"],["أَثَافِيَّ سُفْعًا فِي مُعَرَّسِ مِرْجَلٍ","وَنُؤْيًا كَجِذْمِ الحَوْضِ لَمْ يَتَثَلَّمِ"],["فَلَمَّا عَرَفْتُ الدَّارَ قُلْتُ لِرَبْعِهَا","أَلَا انْعَمْ صَبَاحًا أَيُّهَا الرَّبْعُ وَاسْلَمِ"],["تَبَصَّرْ خَلِيلِي هَلْ تَرَى مِنْ ظَعَائِنٍ","تَحَمَّلْنَ بِالعَلْيَاءِ مِنْ فَوْقِ جُرْثُمِ"],["جَعَلْنَ القَنَانَ عَنْ يَمِينٍ وَحَزْنَهُ","وَكَمْ بِالقَنَانِ مِنْ مُحِلٍّ وَمُحْرِمِ"],["عَلَوْنَ بِأَنْمَاطٍ عِتَاقٍ وَكِلَّةٍ","وِرَادٍ حوَاشيهَا مُشَاكهة الدّمِ"],["وَوَرَّكْنَ فِي السُّوبَانِ يَعْلُونَ مَتْنَهُ","عَلَيْهِنَّ دَلُّ النَّاعِمِ الْمُتَنَعِّمِ"],["بَكَرْنَ بُكُورًا وَاسْتَحَرْنَ بِسُحْرَةٍ","فَهُنَّ وَوَادِي الرَّسِّ كَاليَدِ لِلْفَمِ"],["وَفِيهِنَّ مَلْهًى لِلَّطِيفِ وَمَنْظَرٌ","أَنِيقٌ لِعَيْنِ النَّاظِرِ الْمُتَوَسِّمِ"],["كَأَنَّ فُتَاتَ العِهْنِ فِي كُلِّ مَنْزِلٍ","نَزَلْنَ بِهِ حَبُّ الفَنَا لَمْ يُحَطَّمِ"],["فَلَمَّا وَرَدْنَ المَاءَ زُرْقًا جِمَامُهُ","وَضَعْنَ عِصِيّ الحَاضِرِ الْمُتَخَيِّمِ"],["ظَهَرْنَ مِنَ السُّوبَانِ ثُمَّ جَزَعْنَهُ","عَلَى كُلِّ قَيْنِيٍّ قَشِيبٍ وَمُفْأَمِ"],["فَأَقْسَمْتُ بِالْبَيْتِ الَّذِي طَافَ حَوْلَهُ","رِجَالٌ بَنَوْهُ مِنْ قُرَيْشٍ وَجُرْهُمِ"],["يَمِينًا لَنِعْمَ السَّيِّدَانِ وُجِدْتُمَا","عَلَى كُلِّ حَالٍ مِنْ سَحِيلٍ وَمُبْرَمِ"],["تَدَارَكْتُمَا عَبْسًا وَذُبيَانَ بَعْدَمَا","تَفَانَوا وَدَقّوا بَيْنَهُمْ عِطْرَ مَنْشِمِ"],["وَقَدْ قُلْتُمَا إِنْ نُدْرِكِ السِّلْمَ وَاسِعًا","بِمَالٍ وَمَعْرُوفٍ مِنَ القَوْلِ نَسْلَمِ"],["فَأَصْبَحْتُمَا مِنْهَا عَلَى خَيْرِ مَوْطِنٍ","بَعِيدَيْنِ فِيهَا مِنْ عُقُوقٍ وَمَأْثَمِ"],["عَظِيمَيْنِ فِي عُلْيَا مَعَدٍّ هُدِيتُمَا","وَمَنْ يَسْتَبِحْ كَنْزًا مِنَ الْمَجْدِ يَعْظُمِ"],["تُعَفَّى الكُلُومُ بِالْمِئِينَ فَأَصْبَحَتْ","يُنَجِّمُهَا مَنْ لَيْسَ فِيهَا بِمُجْرِمِ"],["يُنَجِّمُهَا قَوْمٌ لِقَوْمٍ غَرَامَةً","وَلَمْ يُهَرِيقُوا بَيْنَهُمْ مِلْءَ مِحْجَمِ"],["فَأَصْبَحَ يَجْرِي فِيهِمُ مِنْ تِلَادِكُمْ","مَغَانِمُ شَتَّى مِنْ إِفَالٍ مُزَنَّمِ"],["أَلَا أَبْلِغِ الأَحْلَافَ عَنِّي رِسَالَةً","وَذُبْيَانَ هَلْ أَقْسَمْتُمُ كُلَّ مُقْسَمِ"],["فَلَا تَكْتُمُنَّ اللهَ مَا فِي نُفُوسِكُمْ","لِيَخْفَى وَمَهْمَا يُكْتَمِ اللهُ يَعْلَمِ"],["يُؤَخَّرْ فَيُوضَعْ فِي كِتَابٍ فَيُدَّخَرْ","لِيَوْمِ الْحِسَابِ أَوْ يُعَجَّلْ فَيُنْقَمِ"],["وَمَا الْحَرْبُ إِلَّا مَا عَلِمْتُمْ وَذُقْتُمُ","وَمَا هُوَ عَنْهَا بِالْحَدِيثِ الْمُرَجَّمِ"],["مَتَى تَبْعَثُوهَا تَبْعَثُوهَا ذَمِيمَةً","وَتَضْرَ إِذَا ضَرَّيْتُمُوهَا فتَضْرَمِ"],["فَتَعْرُكُكُمْ عَرْكَ الرَّحَى بِثِفَالِهَا","وَتَلْقَحْ كِشَافًا ثُمَّ تُنْتَجْ فَتُتْئِمِ"],["فَتُنْتِجْ لَكُمْ غِلْمَانَ أَشْأَمَ كُلُّهُمْ","كَأَحْمَرِ عَادٍ ثُمَّ تُرْضِعْ فَتَفْطِمِ"],["فَتُغْلِلْ لَكُمْ مَا لَا تُغِلُّ لِأَهْلِهَا","قُرًى بِالعِرَاقِ مِنْ قَفِيزٍ وَدِرْهَمِ"],["لَعَمْرِي لَنِعْمَ الْحَيُّ جَرَّ عَلَيْهِمُ","بِمَا لَا يُؤَاتيهمْ حُصَيْنُ بْنُ ضَمْضَمِ"],["وَكَانَ طَوَى كَشْحًا عَلَى مُسْتَكِنَّةٍ","فَلَا هُوَ أَبْدَاهَا وَلَمْ يَتَقَدَّمِ"],["وَقَالَ سَأَقْضِي حَاجَتِي ثُمَّ أَتَّقِي","عَدُوِّي بِأَلْفٍ مِنْ وَرَائِيَ مُلْجَمِ"],["فَشَدَّ فَلَمْ يُفْزِعْ بُيُوتًا كَثِيرَةً","لدَى حَيْثُ أَلْقَتْ رَحْلَهَا أُمُّ قَشْعَمِ"],["لَدَى أَسَدٍ شَاكِي السِّلَاحِ مُقَذَّفٍ","لَهُ لِبَدٌ أَظْفَارُهُ لَمْ تُقَلَّمِ"],["جَرِيءٍ مَتَى يُظْلَمْ يُعَاقِبْ بِظُلْمِهِ","سَرِيعًا وَإِلَّا يُبْدَ بِالظُّلْمِ يَظْلِمِ"],["رَعَوا ظِمْأَهُمْ حَتَّى إِذَا تَمَّ أَوْرَدُوا","غِمَارًا تَفَرَّى بِالسِّلَاحِ وَبِالدَّمِ"],["فَقَضَّوا مَنَايَا بَيْنَهُمْ ثُمَّ أَصْدَرُوا","إِلَى كَلأٍ مُسْتَوْبَلٍ مُتَوَخِّمِ"],["لَعَمْرُكَ مَا جَرَّتْ عَلَيْهِمْ رِمَاحُهُمْ","دَمَ ابْنِ نَهِيكٍ أَوْ قَتِيلِ الْمُثَلَّمِ"],["وَلَا شَارَكَتْ فِي الْمَوْتِ فِي دَمِ نَوْفَلٍ","وَلَا وَهَبٍ مِنْهَا وَلَا ابْنِ الْمُخَزَّمِ"],["فَكُلًّا أَرَاهُمْ أَصْبَحُوا يَعْقِلُونَهُ","صَحيحَاتِ مالٍ طالِعَاتٍ بِمَخْرِمِ"],["لِحَيٍّ حِلَالٍ يَعْصِمُ النَّاسَ أَمْرُهُمْ","إِذَا طَرَقَتْ إِحْدَى اللَّيَالِي بِمُعْظَمِ"],["كِرَامٍ فَلَا ذُو الضِّغْنِ يُدْرِكُ تَبْلَهُ","وَلَا الجَارِمُ الْجَانِي عَلَيْهِمْ بِمُسْلَمِ"],["سَئِمْتُ تَكَالِيفَ الْحَيَاةِ وَمَنْ يَعِشْ","ثَمَانِينَ حَوْلًا لَا أَبَا لَكَ يَسْأَمِ"],["وَأَعْلَمُ مَا فِي الْيَوْمِ وَالأَمْسِ قَبْلَهُ","وَلَكِنَّنِي عَنْ عِلْمِ مَا فِي غَدٍ عَمِي"],["رَأَيْتُ الْمَنَايَا خَبْطَ عَشْوَاءَ مَنْ تُصِبْ","تُمِتْهُ وَمَنْ تُخْطِئْ يُعَمَّرْ فَيَهْرَمِ"],["وَمَنْ لَمْ يُصَانِعْ فِي أُمُورٍ كَثِيرَةٍ","يُضَرَّسْ بِأَنْيَابٍ وَيُوطَأْ بِمَنْسِمِ"],["وَمَنْ يَجْعَلِ المَعْرُوفَ مِنْ دُونِ عِرْضِهِ","يَفِرْهُ وَمَنْ لَا يَتَّقِ الشَّتْمَ يُشْتَمِ"],["وَمَنْ يَكُ ذَا فَضْلٍ فَيَبْخَلْ بِفَضْلِهِ","عَلَى قَوْمِهِ يُسْتَغْنَ عَنْهُ وَيُذْمَمِ"],["وَمَنْ يُوفِ لَا يُذْمَمْ وَمَنْ يُهْدَ قَلْبُهُ","إِلَى مُطْمَئِنِّ البِرِّ لَا يَتَجَمْجَمِ"],["وَمَنْ هَابَ أَسْبَابَ الْمَنَايَا يَنَلْنَهُ","وَإِنْ يَرْقَ أَسْبَابَ السَّمَاءِ بِسُلَّمِ"],["وَمَنْ يَجْعَلِ الْمَعْرُوفَ فِي غَيْرِ أَهْلِهِ","يَكُنْ حَمْدُهُ ذَمًّا عَلَيْهِ وَيَنْدَمِ"],["وَمَنْ يَعْصِ أَطْرَافَ الزِّجَاجِ فَإِنَّهُ","يُطيعُ العَوَالِي رُكِّبَتْ كُلَّ لَهْذَمِ"],["وَمَنْ لَمْ يَذُدْ عَنْ حَوْضِهِ بِسِلَاحِهِ","يُهَدَّمْ وَمَنْ لَا يَظْلِمِ النَّاسَ يُظْلَمِ"],["وَمَنْ يَغْتَرِبْ يَحْسِبْ عَدُوًّا صَدِيقَهُ","وَمَنْ لَمْ يُكَرِّمْ نَفْسَهُ لَمْ يُكَرَّمِ"],["وَمَهْمَا تَكُنْ عِنْدَ امْرِئٍ مِنْ خَلِيقَةٍ","وَإِنْ خَالَهَا تَخْفَى عَلَى النَّاسِ تُعْلَمِ"],["وَكَائِنْ تَرَى مِنْ صَامِتٍ لَكَ مُعْجِبٍ","زِيَادَتُهُ أَوْ نَقْصُهُ فِي التَّكَلُّمِ"],["لِسَانُ الفَتَى نِصْفٌ وَنِصْفٌ فُؤَادُهُ","فَلَمْ يَبْقَ إِلَّا صُورَةُ اللَّحْمِ وَالدَّمِ"],["وَإِنَّ سَفَاهَ الشَّيْخِ لَا حِلْمَ بَعْدَهُ","وَإِنَّ الفَتَى بَعدَ السّفَاهَةِ يَحْلُمِ"],["سَأَلْنَا فَأَعْطَيْتُمْ وَعُدْنَا فَعُدْتُمُ","وَمَنْ أَكْثَرَ التَّسْآلَ يَوْمًا سَيُحْرَمِ"]],"secs":{"1":"معلقة زهير بن أبي سلمى"}}],"sharh":false};
